import sys; sys.path.insert(0,'/root/work')
from ising import *
rng=np.random.default_rng(0)
def brute(W,H,K):
  N=W*H
  sp=np.array(list(itertools.product((-1,1),repeat=N))).reshape(-1,H,W)
  E=sum(K[2*(x+W*y)]*sp[:,y,x]*sp[:,y,(x+1)%W]+K[2*(x+W*y)+1]*sp[:,y,x]*sp[:,(y+1)%H,x] for x in range(W) for y in range(H))
  return np.exp(E).sum()/2**N/np.prod(np.cosh(K))
for W,H in [(4,3),(3,4),(4,4)]:
 for name,par in [('a',lambda L:(L-1)%2), ('b',lambda L:1), ('c',lambda L:0), ('d',lambda L:L%2)]:
  try: m=Model(W,H,par)
  except AssertionError as e: print('inc');continue
  for t in range(2):
    K=rng.uniform(-0.35,0.9,2*W*H); w=np.tanh(K)
    S=brute(W,H,K)
    pf=[ (lambda r:r[0]*np.exp(r[1]))(pfaffian_schur(A)) for A,_ in m.pf_terms(w)]
    print(W,H,name,S,np.round(np.array(pf)/S,4))
EOF
